-- ============================================================
-- Quiz coverage for databases/postgresql and databases/mysql
-- (overview, fundamentals, intermediate, advanced -- all four
-- tabs exist and carry substantive live content for both).
-- Phase 4 (Databases academy), batch 1: PostgreSQL & MySQL.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/postgresql/overview ----------
('databases', 'postgresql', 'overview', 'What makes PostgreSQL''s JSONB type different from just storing raw JSON as TEXT?', '["JSONB is purely cosmetic -- it behaves identically to TEXT", "JSONB stores data in a decomposed binary format that supports indexing (e.g. with GIN) and efficient containment/key-lookup operators like @> and ->, whereas TEXT requires parsing the whole string on every query", "JSONB can only store arrays, not objects", "JSONB is slower than TEXT for every operation"]', 1, 'The binary, indexed representation is what makes JSONB genuinely queryable at scale -- a GIN index on a JSONB column lets containment queries use an index scan instead of scanning and re-parsing every row.', 'beginner'),
('databases', 'postgresql', 'overview', 'What is MVCC (Multi-Version Concurrency Control), and why does it matter for PostgreSQL?', '["A backup strategy for disaster recovery", "A concurrency model where each transaction sees a consistent snapshot of the data, so readers never block writers and writers never block readers -- instead of locking rows for reads, PostgreSQL keeps multiple versions of a row and lets each transaction see the version consistent with its own snapshot", "A replication protocol for streaming changes to replicas", "A type of index used for full-text search"]', 1, 'MVCC is the mechanism that lets PostgreSQL handle high concurrency well -- but it has a real cost: old row versions accumulate as dead tuples and need VACUUM to reclaim that space.', 'intermediate'),
('databases', 'postgresql', 'overview', 'Why does PostgreSQL offer index types beyond the default B-tree, such as GIN, GiST, and BRIN?', '["They are legacy types kept only for backward compatibility", "Different data shapes and query patterns need different index structures -- GIN suits JSONB/array/full-text containment queries, GiST suits geometric and range types, and BRIN is efficient for huge, naturally-ordered tables like time-series logs where a full B-tree would be unnecessarily large", "PostgreSQL requires a different index type for every table regardless of its data", "GIN, GiST, and BRIN are all interchangeable with no real tradeoffs"]', 1, 'Picking the right index type for the query pattern and data shape is a core PostgreSQL skill -- a B-tree on a JSONB column, for example, will not accelerate a containment (@>) query the way a GIN index will.', 'intermediate'),
('databases', 'postgresql', 'overview', 'What does the `\\x` command do in psql?', '["Deletes the current database", "Toggles expanded output, which displays each column on its own line instead of a wide table row -- useful when a query returns many columns or long values that would otherwise wrap illegibly", "Executes an external shell command", "Shows query execution timing"]', 1, 'Expanded output is one of the most-used psql conveniences once tables get wide enough that the default row-per-line format becomes hard to read.', 'beginner'),
('databases', 'postgresql', 'overview', 'Why might a team choose PostgreSQL over MySQL for a new application with complex analytical queries?', '["PostgreSQL is always faster than MySQL for every workload with no exceptions", "PostgreSQL has stronger support for advanced indexing (GIN/GiST/BRIN, partial and expression indexes), full window function support, and native JSONB/array types -- features that matter more as query complexity grows, whereas MySQL's strengths lean toward simpler, high-throughput read patterns", "MySQL cannot run SELECT statements with more than one JOIN", "PostgreSQL is the only database that supports transactions"]', 1, 'The choice is workload-dependent, not a strict hierarchy -- PostgreSQL''s advantages are most pronounced for complex queries, semi-structured data, and standards compliance, while MySQL remains a strong, simpler choice for many read-heavy, straightforward-schema applications.', 'beginner'),

-- ---------- databases/postgresql/fundamentals ----------
('databases', 'postgresql', 'fundamentals', 'Why is `TIMESTAMPTZ` generally preferred over plain `TIMESTAMP` in PostgreSQL?', '["TIMESTAMPTZ takes up less disk space", "TIMESTAMP silently discards timezone information, which becomes a real bug the moment the application, database server, or a future deployment spans more than one timezone; TIMESTAMPTZ stores the instant in time unambiguously", "TIMESTAMP cannot store dates before the year 2000", "There is no functional difference -- it is purely a style preference"]', 1, 'This is one of the most common real-world PostgreSQL mistakes -- choosing TIMESTAMP by habit works fine until the system crosses a timezone boundary, at which point the ambiguity becomes an actual data-correctness bug.', 'beginner'),
('databases', 'postgresql', 'fundamentals', 'What does `ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name` accomplish?', '["It deletes any row with a duplicate email", "It performs an atomic upsert -- if a row with that email already exists, it updates the name column of the existing row instead of raising a unique-constraint violation; EXCLUDED refers to the row that was proposed for insertion", "It only works if the table has no primary key", "It silently ignores the insert without doing anything"]', 1, 'ON CONFLICT is PostgreSQL''s native upsert mechanism -- it avoids the race condition of a separate SELECT-then-INSERT-or-UPDATE by handling the conflict atomically within a single statement.', 'intermediate'),
('databases', 'postgresql', 'fundamentals', 'In a composite index like `(user_id, status, created_at)`, which query below can actually use the index efficiently?', '["WHERE status = ''pending'' (alone)", "WHERE user_id = 1 AND status = ''pending'' -- because the leftmost-prefix rule means a composite index can be used efficiently when the query filters on a contiguous prefix of the indexed columns, starting from the leftmost one", "WHERE created_at > ''2024-01-01'' (alone)", "None of the above can use this index"]', 1, 'The leftmost-prefix rule is central to composite indexing in PostgreSQL (and most relational databases) -- skipping the first column in the index means the index generally cannot be used efficiently for that query.', 'intermediate'),
('databases', 'postgresql', 'fundamentals', 'What is the practical difference between `EXPLAIN` and `EXPLAIN ANALYZE`?', '["They produce identical output", "EXPLAIN shows the planner''s estimated execution plan without running the query; EXPLAIN ANALYZE actually executes the query and shows real timings and row counts alongside the plan, which is essential for spotting where the planner''s estimates were wrong", "EXPLAIN ANALYZE only works on INSERT statements", "EXPLAIN is only available in PostgreSQL 16 and later"]', 1, 'EXPLAIN ANALYZE is the more useful diagnostic tool in practice because a large gap between estimated and actual rows is often the first clue that table statistics are stale and an ANALYZE is needed.', 'beginner'),
('databases', 'postgresql', 'fundamentals', 'What does `SELECT ... FOR UPDATE SKIP LOCKED` enable, and what is it commonly used for?', '["It permanently locks a table against all future writes", "It lets a transaction select and lock rows while skipping any rows that are already locked by another transaction, rather than waiting for them -- this is the standard pattern for building a job queue where multiple workers pull different pending jobs concurrently without blocking each other", "It disables row-level locking entirely for that query", "It is only valid inside a read-only transaction"]', 1, 'SKIP LOCKED is specifically designed for concurrent queue-processing patterns -- without it, multiple workers running a naive SELECT ... FOR UPDATE would serialize on the same rows instead of picking up different available jobs.', 'advanced'),

-- ---------- databases/postgresql/intermediate ----------
('databases', 'postgresql', 'intermediate', 'What does `CREATE INDEX CONCURRENTLY` do differently from a plain `CREATE INDEX`?', '["It builds the index faster in every case", "It builds the index without holding a lock that blocks concurrent writes to the table, at the cost of taking longer and requiring two table scans -- this is the standard way to add an index to a live production table without an outage", "It creates the index only in memory, never persisting it to disk", "It is required for every index in PostgreSQL 16+"]', 1, 'CONCURRENTLY trades speed and some robustness (it can fail and leave an invalid index that must be dropped and retried) for avoiding the exclusive lock that a normal CREATE INDEX would hold, which matters a great deal on a busy production table.', 'advanced'),
('databases', 'postgresql', 'intermediate', 'What is a partial index, and when is it useful?', '["An index that only covers half of a table''s rows at random", "An index built with a WHERE clause so it only includes rows matching a condition (e.g. WHERE status = ''pending'') -- useful when queries consistently filter on that condition, since the resulting index is much smaller and faster than indexing the entire table", "An index that is automatically dropped after 30 days", "A deprecated PostgreSQL feature replaced by expression indexes"]', 1, 'Partial indexes are a genuine size/performance win when a query pattern consistently targets a small, well-defined subset of rows -- indexing only that subset avoids the overhead of indexing rows that will never be searched that way.', 'intermediate'),
('databases', 'postgresql', 'intermediate', 'Why does range partitioning by date (e.g. `PARTITION BY RANGE (created_at)`) improve query performance for time-series data?', '["It compresses the data automatically", "Partition pruning lets the query planner skip scanning partitions entirely outside the queried date range, so a query filtering to a single month only touches that month''s partition instead of the entire table''s history", "Partitioning removes the need for indexes altogether", "It only helps INSERT performance, not SELECT performance"]', 1, 'Partition pruning is the core benefit -- for a table with years of historical data, a query scoped to a recent time window can skip the vast majority of the table entirely, purely based on partition boundaries.', 'advanced'),
('databases', 'postgresql', 'intermediate', 'What problem does `SELECT array_agg(x ORDER BY x) INTO sorted FROM unnest(state) x;` solve inside a PL/pgSQL function, and why is the explicit `SELECT ... INTO` form required?', '["It is optional stylistic preference -- `sorted := array_agg(x ORDER BY x) FROM unnest(state) x;` works identically", "PL/pgSQL assignment (`:=`) only accepts a scalar expression, not a query with a FROM clause -- to assign the result of an actual SQL query (including one with a FROM clause) to a variable, PL/pgSQL requires the explicit `SELECT ... INTO variable FROM ...` form", "unnest() cannot be used inside PL/pgSQL functions at all", "array_agg() requires a GROUP BY clause to work"]', 1, 'This is a real, common PL/pgSQL syntax mistake -- writing `variable := expression FROM ...` looks plausible but is not valid PL/pgSQL assignment syntax; querying into a variable always requires the explicit SELECT ... INTO form.', 'advanced'),
('databases', 'postgresql', 'intermediate', 'What is the main use case for logical replication (`CREATE PUBLICATION`/`CREATE SUBSCRIPTION`) compared to physical streaming replication?', '["Logical replication is always faster than physical replication", "Logical replication replicates at the table/row level and can work across different PostgreSQL major versions or replicate only a subset of tables, making it well suited for scenarios like zero-downtime major-version upgrades or selective data syncing -- physical replication clones the entire cluster byte-for-byte and requires matching versions", "Physical replication cannot be used for disaster recovery", "Logical replication does not require a primary key on replicated tables under any circumstances"]', 1, 'The version-independence and table-level granularity of logical replication are what make it useful for migrations and selective syncing, in contrast to physical replication''s simpler but all-or-nothing, same-version cloning model.', 'advanced'),

-- ---------- databases/postgresql/advanced ----------
('databases', 'postgresql', 'advanced', 'What is the practical effect of a table having heavy UPDATE/DELETE churn with autovacuum poorly tuned or disabled?', '["Nothing -- PostgreSQL reclaims space instantly on every UPDATE/DELETE", "Dead row versions (left behind by MVCC) accumulate faster than they''re cleaned up, causing table and index bloat -- the table consumes more disk space than its live data justifies and query performance degrades as scans and indexes have to work through dead tuples", "The database will refuse to accept further writes until manually restarted", "Autovacuum only matters for tables larger than 1TB"]', 1, 'Table bloat from under-vacuumed high-churn tables is one of the most common real PostgreSQL operational issues -- it directly follows from how MVCC keeps old row versions around until VACUUM reclaims them.', 'advanced'),
('databases', 'postgresql', 'advanced', 'What does the pgvector extension''s HNSW index enable, and what kind of query does it accelerate?', '["Exact full-text search across TEXT columns", "Approximate nearest-neighbor search over vector embeddings (e.g. for semantic/similarity search) -- HNSW builds a graph structure that makes finding the closest vectors to a query vector far faster than a brute-force scan comparing against every stored embedding", "Referential integrity checks between related tables", "Automatic conversion of TEXT columns into vector embeddings"]', 1, 'pgvector with an HNSW index is what makes PostgreSQL viable as a vector database for RAG/AI-embedding-search workloads without needing a separate specialized vector database.', 'advanced'),
('databases', 'postgresql', 'advanced', 'Why is `SELECT COUNT(*)` on a large table often slower in PostgreSQL than some developers expect coming from other databases?', '["COUNT(*) is not a valid PostgreSQL function", "Because of MVCC, PostgreSQL doesn''t maintain a single authoritative row count the way MyISAM once did -- it generally has to check visibility for each row against the querying transaction''s snapshot, which for a large table means doing real work rather than returning a cached number", "COUNT(*) always triggers a full table lock", "PostgreSQL caches COUNT(*) results indefinitely, so repeated calls get slower over time"]', 1, 'This is a direct consequence of MVCC: since different transactions can see different sets of live rows, there''s no single global row count PostgreSQL can just look up -- it has to determine visibility per row for the requesting transaction.', 'advanced'),
('databases', 'postgresql', 'advanced', 'What does TimescaleDB''s continuous aggregate feature provide that a regular materialized view does not?', '["Continuous aggregates store data in a completely different database engine", "A continuous aggregate automatically and incrementally refreshes as new data arrives (via a background policy), and query planners can transparently use it to serve queries over already-aggregated time buckets instead of re-scanning raw data -- a regular materialized view requires a manual or scheduled full REFRESH", "Continuous aggregates eliminate the need for any indexes on the underlying hypertable", "Continuous aggregates only work with SUM(), not AVG() or MAX()"]', 1, 'The incremental, automatic refresh combined with query-time transparency is what makes continuous aggregates practical for dashboards over constantly-arriving time-series data, versus the all-or-nothing refresh of a plain materialized view.', 'advanced'),
('databases', 'postgresql', 'advanced', 'In `SELECT balance INTO from_balance FROM accounts WHERE id = from_account_id FOR UPDATE;` inside a fund-transfer procedure, what is the purpose of `FOR UPDATE`?', '["It makes the SELECT run faster by skipping MVCC checks", "It acquires a row-level lock on the selected row for the duration of the transaction, preventing another concurrent transaction from modifying (or also locking for update) that same row until this transaction commits or rolls back -- critical for preventing a lost-update race condition on the balance", "It automatically commits the transaction after the SELECT", "It only has an effect when the table has no primary key"]', 1, 'Without FOR UPDATE, two concurrent transfers could both read the same starting balance before either writes, producing a lost update -- locking the row for the duration of the transaction is what makes the balance check-then-update sequence safe under concurrency.', 'advanced'),

-- ---------- databases/mysql/overview ----------
('databases', 'mysql', 'overview', 'Why should new MySQL tables almost always use the InnoDB storage engine rather than MyISAM?', '["MyISAM is faster for every workload", "InnoDB supports ACID transactions, foreign keys, and row-level locking (better write concurrency), while MyISAM offers none of these and only uses table-level locking -- MyISAM''s main historical advantage (instant COUNT(*)) rarely outweighs losing transactional integrity", "MyISAM cannot store more than 1000 rows per table", "InnoDB and MyISAM are two names for the same engine"]', 1, 'InnoDB has been the default engine since MySQL 5.5 precisely because transactional integrity and row-level locking matter far more for real applications than MyISAM''s narrow read-only performance edge.', 'beginner'),
('databases', 'mysql', 'overview', 'Why should `utf8mb4` be used instead of MySQL''s `utf8` charset?', '["They are identical and utf8mb4 is just a newer alias", "MySQL''s historical `utf8` charset is actually a 3-byte-maximum encoding that cannot represent the full Unicode range, including emoji and some CJK characters -- `utf8mb4` is the genuinely complete UTF-8 implementation and is what should always be used", "utf8mb4 uses less storage than utf8", "utf8 is only usable for numeric columns"]', 1, 'This is a well-known MySQL-specific naming trap -- assuming `utf8` means the same thing it does everywhere else leads to real data-loss bugs when storing emoji or certain CJK characters.', 'beginner'),
('databases', 'mysql', 'overview', 'What does `ON DUPLICATE KEY UPDATE` do in MySQL?', '["It always inserts a new row, ignoring any duplicate key", "It performs an atomic upsert: if the INSERT would violate a unique or primary key constraint, the specified UPDATE runs against the existing row instead of raising an error", "It deletes the existing row before inserting the new one", "It only works on tables without any indexes"]', 1, 'This is MySQL''s equivalent to PostgreSQL''s ON CONFLICT -- an atomic way to insert-or-update without a race condition between a separate check and a subsequent write.', 'beginner'),
('databases', 'mysql', 'overview', 'A reserved word like `key` is used as a column name, e.g. `INSERT INTO counters (key, val) VALUES (...)`. What is wrong with this, and how is it fixed?', '["Nothing is wrong -- reserved words can always be used as identifiers", "`key` is a reserved word in MySQL and will cause a syntax error if used unquoted as a column name -- it must be wrapped in backticks (`` `key` ``) to be used as an identifier", "Reserved words can only be used as table names, never column names", "This only fails in MySQL 5.x, not MySQL 8.x"]', 1, 'Backtick-quoting is MySQL''s mechanism for using a reserved word (or any identifier with special characters/spacing) as a column, table, or database name -- omitting it produces a real syntax error, not just a style issue.', 'intermediate'),
('databases', 'mysql', 'overview', 'When would a team reasonably choose MySQL over PostgreSQL for a new project?', '["Never -- PostgreSQL is strictly superior in every scenario", "When the team already knows MySQL well, the stack is a common MySQL-native combination (e.g. WordPress, a LAMP/LEMP stack), or when using MySQL-specific managed tooling like PlanetScale/Vitess -- the right choice depends on team familiarity and ecosystem fit, not a universal ranking", "MySQL is required whenever using Docker", "MySQL cannot be used with any cloud provider"]', 1, 'Database choice is workload- and ecosystem-dependent -- MySQL remains a strong, well-supported choice for many applications, particularly where the team''s existing expertise or tooling ecosystem already centers on it.', 'beginner'),

-- ---------- databases/mysql/fundamentals ----------
('databases', 'mysql', 'fundamentals', 'What replaced `SHOW SLAVE STATUS` and `CHANGE MASTER TO` in current MySQL, and why does this matter when following older tutorials?', '["Nothing replaced them -- they still work identically in all MySQL versions", "MySQL renamed replication terminology starting in 8.0.23 (`SHOW REPLICA STATUS`, `CHANGE REPLICATION SOURCE TO`, `START/STOP REPLICA`) and removed the old master/slave commands entirely in the 8.4 LTS release -- a lot of tutorials predating this change still show the old, now-nonfunctional syntax", "The old commands were renamed only in MySQL 5.7 and reverted in 8.0", "SHOW SLAVE STATUS was never a real MySQL command"]', 1, 'This is a genuinely common trap for anyone learning from older material -- code that looks correct and well-documented online may simply error out on a current MySQL install because the underlying commands no longer exist.', 'intermediate'),
('databases', 'mysql', 'fundamentals', 'In a composite index `(user_id, status, created_at)`, why does `WHERE status = ?` alone fail to use the index efficiently?', '["MySQL composite indexes only support up to 2 columns", "The leftmost-prefix rule means a composite index can only be used efficiently when the query filters on a contiguous prefix starting from the leftmost column -- skipping user_id (the first column) to filter only on status means the index generally cannot be used for that lookup", "status columns can never be indexed in MySQL", "This actually works fine and uses the index"]', 1, 'The leftmost-prefix rule applies identically across most relational databases with composite B-tree indexes -- column order in the index definition determines which query patterns it can actually accelerate.', 'intermediate'),
('databases', 'mysql', 'fundamentals', 'What is the practical difference between `SELECT ... FOR UPDATE` and `SELECT ... LOCK IN SHARE MODE` in InnoDB?', '["They are identical -- both are deprecated aliases for the same lock", "FOR UPDATE takes an exclusive lock (blocking other transactions from reading-for-update or writing that row), while LOCK IN SHARE MODE takes a shared lock (allows other transactions to also read-lock the row, but blocks writes) -- the choice depends on whether you're about to modify the row or just need to ensure it doesn't change underneath a read", "LOCK IN SHARE MODE only works on MyISAM tables", "FOR UPDATE releases its lock immediately after the SELECT completes, before the transaction commits"]', 1, 'Choosing the right lock mode matters for both correctness and concurrency -- an exclusive lock (FOR UPDATE) is appropriate when you intend to modify the row, while a shared lock is enough when you just need to prevent it from changing during your read.', 'advanced'),
('databases', 'mysql', 'fundamentals', 'What does MySQL''s default `REPEATABLE READ` isolation level prevent that `READ COMMITTED` does not?', '["Nothing -- they provide identical guarantees", "REPEATABLE READ prevents non-repeatable reads (the same query returning different results if re-run within the same transaction), which READ COMMITTED does not guard against, since READ COMMITTED lets each individual statement see the latest committed data even within one transaction", "READ COMMITTED prevents dirty reads while REPEATABLE READ allows them", "REPEATABLE READ is not a real MySQL isolation level"]', 1, 'Isolation level choice trades off consistency guarantees against concurrency -- REPEATABLE READ (InnoDB''s default) gives a transaction a consistent view across all its statements, which READ COMMITTED does not guarantee.', 'advanced'),
('databases', 'mysql', 'fundamentals', 'Why does a JSON column benefit from a generated/virtual column with a regular index, rather than indexing the JSON column directly?', '["JSON columns cannot be queried at all without this technique", "MySQL cannot directly build a standard B-tree index on an entire JSON document''s contents -- extracting a specific JSON field into a generated column (e.g. via JSON_EXTRACT) and indexing that generated column lets MySQL use a normal, efficient index for queries filtering on that specific field", "Generated columns are required for all JSON storage in MySQL", "This technique only works in MySQL 5.7, not MySQL 8.0+"]', 1, 'This generated-column-plus-index pattern is the standard MySQL technique for making a specific JSON field efficiently searchable, since MySQL''s JSON indexing support works differently from PostgreSQL''s native GIN indexing on JSONB.', 'advanced'),

-- ---------- databases/mysql/intermediate ----------
('databases', 'mysql', 'intermediate', 'What does `EXPLAIN`''s `type: ALL` mean, and why is it generally something to fix?', '["ALL means the query used every available index simultaneously, which is ideal", "type: ALL means MySQL is performing a full table scan, reading every row rather than using an index to narrow the search -- on a large table this is usually the sign of a missing or unusable index for that query''s WHERE/JOIN conditions", "ALL is a normal, expected value with no performance implication", "type: ALL only appears for INSERT statements, never SELECT"]', 1, 'The type column in EXPLAIN output is one of the first things to check when diagnosing a slow query -- ALL at the top of the access-type hierarchy (system > const > ref > range > index > ALL) signals the least efficient access pattern.', 'intermediate'),
('databases', 'mysql', 'intermediate', 'Why is index selectivity (`COUNT(DISTINCT column)/COUNT(*)`) relevant when deciding what to index?', '["Selectivity has no relationship to whether an index will actually be useful", "A high-selectivity column (many distinct values relative to row count) makes a much more effective index candidate than a low-selectivity one, because an index on a low-cardinality column (e.g. a boolean status flag) narrows the search far less and the query planner may skip using it in favor of a full scan anyway", "Low selectivity always means an index will be used", "Selectivity only matters for full-text indexes, not B-tree indexes"]', 1, 'Indexing a column with very few distinct values (like a boolean) often provides little benefit, since the index still points to a large fraction of the table''s rows -- selectivity is a key factor in deciding which columns are actually worth indexing.', 'intermediate'),
('databases', 'mysql', 'intermediate', 'What is the practical benefit of GTID-based replication over classic file/position-based replication?', '["GTID replication is not compatible with InnoDB", "GTID (Global Transaction ID) assigns a unique identifier to every transaction across all servers, which simplifies replication setup and failover by removing the need to manually track and specify binlog file names and positions when configuring a new replica or promoting a replica after a failover", "GTID replication only works for single-statement transactions", "GTID replication requires MyISAM tables specifically"]', 1, 'The automatic, position-independent transaction tracking that GTID provides is what makes modern MySQL replication setup and recovery significantly less error-prone than manually specifying binlog file/position pairs.', 'advanced'),
('databases', 'mysql', 'intermediate', 'Why does MySQL automatically roll back the "smaller" transaction when it detects a deadlock, rather than simply blocking both transactions indefinitely?', '["MySQL cannot detect deadlocks and relies on a query timeout instead", "InnoDB actively monitors for deadlocks (a cycle of transactions each waiting on a lock the other holds) and automatically rolls back one of them (typically the one that has done less work) so the other can proceed -- without this, both transactions would wait on each other forever", "Rolling back a transaction on deadlock is optional and must be manually enabled", "Deadlock detection only works between transactions on the same table"]', 1, 'Automatic deadlock detection and rollback is what prevents a true deadlock from hanging both transactions forever -- InnoDB resolves the cycle by sacrificing one transaction so the system as a whole can make progress.', 'advanced'),
('databases', 'mysql', 'intermediate', 'What does a covering index accomplish, and why is `SELECT *` a common way to accidentally defeat one?', '["A covering index removes the need for a WHERE clause entirely", "A covering index includes every column a query needs directly in the index itself, letting MySQL satisfy the query from the index alone without a separate lookup into the actual table rows -- selecting `SELECT *` typically requires columns not present in the index, forcing MySQL back to the table and losing that benefit", "Covering indexes only apply to primary keys", "SELECT * always uses a covering index automatically if one exists"]', 1, 'The index-only-scan performance benefit of a covering index depends entirely on the query only needing columns that are actually present in that index -- selecting extra columns not covered by the index reintroduces the table lookup the covering index was meant to avoid.', 'intermediate'),

-- ---------- databases/mysql/advanced ----------
('databases', 'mysql', 'advanced', 'What problem does Vitess solve for MySQL at scale, and what is a "shard" in that context?', '["Vitess replaces MySQL entirely with a NoSQL engine", "Vitess is a horizontal sharding layer sitting on top of MySQL -- a shard is one physical MySQL instance holding a portion of the overall dataset (determined by a vindex/shard key), and the app connects to VTGate, a query router, rather than directly to any individual MySQL instance", "A shard in Vitess refers to a database backup file", "Vitess only works with MyISAM tables"]', 1, 'Vitess is specifically designed for the scale where a single MySQL instance (even a well-tuned one) can no longer hold or serve the full dataset, splitting data across many MySQL instances while presenting something closer to a single logical database to the application.', 'advanced'),
('databases', 'mysql', 'advanced', 'What does ProxySQL''s query-routing capability commonly enable in a primary/replica MySQL setup?', '["It replaces the need for any replicas entirely", "It can route SELECT statements to read replicas while sending writes to the primary, based on pattern-matching rules -- allowing an application to connect to a single endpoint without needing read/write-split logic built into the application code itself", "ProxySQL can only route traffic to a single fixed MySQL instance", "ProxySQL requires modifying the application''s SQL syntax"]', 1, 'Offloading read/write splitting to a proxy layer like ProxySQL is a common way to scale read capacity across replicas without adding that routing complexity into every application that talks to the database.', 'advanced'),
('databases', 'mysql', 'advanced', 'Why does range partitioning on `YEAR(created_at)` allow MySQL to skip scanning irrelevant partitions for a date-range query?', '["Partitioning has no effect on which data is scanned -- it only affects storage layout", "Partition pruning lets MySQL determine, from the query''s date range, which partitions could possibly contain matching rows, and skip reading any partition entirely outside that range -- for a query scoped to 2024, a partition holding only 2022 data is never touched", "Partitioning requires rebuilding the entire table on every query", "Partition pruning only works with InnoDB, not with partitioned tables generally"]', 1, 'The performance win from partitioning time-series data comes specifically from pruning -- the query only has to scan the partitions that could actually contain matching rows, not the whole table''s history.', 'advanced'),
('databases', 'mysql', 'advanced', 'Why might `SET GLOBAL innodb_buffer_pool_size = ...` require a server restart on older MySQL versions but not necessarily on current ones?', '["innodb_buffer_pool_size has never been resizable without a restart, on any version", "Newer MySQL versions support online (dynamic) resizing of the InnoDB buffer pool, whereas older setups may require a restart for the change to take effect -- this matters operationally because a restart means a brief outage or failover event on a production system", "The buffer pool size can only ever be set at compile time, never at runtime", "Resizing the buffer pool always requires dropping and recreating all indexes"]', 1, 'Whether a configuration change requires a restart has real operational consequences on a live production database -- confirming a setting is dynamically adjustable (vs. requiring a restart) before touching it in production is a genuinely practical skill, not just trivia.', 'advanced'),
('databases', 'mysql', 'advanced', 'What is a covering-index or index-only benefit specific to how ProxySQL''s query caching rule (`cache_ttl`) is used in the example `INSERT INTO mysql_query_rules (rule_id, active, match_pattern, cache_ttl) VALUES (3, 1, ''^SELECT count\\(\\*\\) FROM products'', 60000)`?', '["It permanently caches the result regardless of underlying data changes, with no expiry", "It caches the result of that specific matched query pattern for 60000 milliseconds (60 seconds), which is useful for expensive-but-slowly-changing queries like a product count, trading a bounded staleness window for avoiding repeated expensive computation on every request", "cache_ttl values in ProxySQL are specified in hours, not milliseconds", "This rule caches write queries (INSERT/UPDATE), not read queries"]', 1, 'ProxySQL''s query cache is a deliberate staleness-for-performance tradeoff -- appropriate for queries like aggregate counts where being up to 60 seconds stale is an acceptable cost for avoiding repeated expensive computation.', 'advanced');
